package com.cloudinfra.sdk.processing;

import java.io.File;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.concurrent.ConcurrentHashMap;
import java.util.UUID;

/**
 * Native image processing bridge for cloud upload pipeline.
 * Uses optimized C library for thumbnail generation and metadata extraction.
 * Thread-safe implementation with upload session tracking.
 */
public class NativeImageProcessor {

    private static final int MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB
    private static final int HEADER_MAGIC_OFFSET = 0;
    private static final int HEADER_SIZE_OFFSET = 8;
    private static final int HEADER_TOTAL_LENGTH = 16;
    private static final byte[] VALID_MAGIC = {0x49, 0x4D, 0x47, 0x50, 0x52, 0x4F, 0x43, 0x31};

    private static final ConcurrentHashMap<String, ProcessingSession> activeSessions = new ConcurrentHashMap<>();

    static {
        System.loadLibrary("cloudimgproc");
    }

    // Native methods - implemented in libcloudimgproc.so
    private static native long nativeAllocateBuffer(int size);
    private static native void nativeFreeBuffer(long bufferPtr);
    private static native int nativeProcessImage(long bufferPtr, int bufferSize, long outputPtr, int outputMaxSize);
    private static native int nativeExtractMetadata(long bufferPtr, int bufferSize, byte[] metadataOut);

    /**
     * Represents an active processing session with native resource tracking.
     */
    private static class ProcessingSession {
        final String sessionId;
        final long nativeBufferPtr;
        final int allocatedSize;
        volatile boolean released;
        final long createdAt;

        ProcessingSession(String sessionId, long nativeBufferPtr, int allocatedSize) {
            this.sessionId = sessionId;
            this.nativeBufferPtr = nativeBufferPtr;
            this.allocatedSize = allocatedSize;
            this.released = false;
            this.createdAt = System.currentTimeMillis();
        }
    }

    /**
     * Validates the upload header format before native processing.
     * Returns the declared payload size from the header.
     */
    private static int validateAndExtractSize(byte[] data) throws SecurityException {
        if (data == null || data.length < HEADER_TOTAL_LENGTH) {
            throw new SecurityException("Invalid upload: insufficient header data");
        }

        byte[] magic = Arrays.copyOfRange(data, HEADER_MAGIC_OFFSET, HEADER_MAGIC_OFFSET + 8);
        if (!Arrays.equals(magic, VALID_MAGIC)) {
            throw new SecurityException("Invalid upload: bad magic bytes");
        }

        // Extract declared size from header (little-endian 64-bit)
        long declaredSize = 0;
        for (int i = 0; i < 8; i++) {
            declaredSize |= ((long)(data[HEADER_SIZE_OFFSET + i] & 0xFF)) << (i * 8);
        }

        // Validate size bounds
        if (declaredSize <= 0 || declaredSize > MAX_FILE_SIZE) {
            throw new SecurityException("Invalid upload: size out of bounds (" + declaredSize + ")");
        }

        return (int) declaredSize;
    }

    /**
     * Computes integrity hash for audit logging.
     */
    private static byte[] computeIntegrityHash(byte[] data, int offset, int length) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            digest.update(data, offset, length);
            return digest.digest();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-256 not available", e);
        }
    }

    /**
     * Primary entry point for processing user-uploaded image data.
     * Performs validation, allocates native buffer, and invokes native processing.
     *
     * @param uploadData Raw bytes from user upload (header + payload)
     * @return Processing result with metadata and thumbnail
     */
    public static ProcessingResult processUpload(byte[] uploadData) throws SecurityException, IOException {
        // Step 1: Validate header and extract declared size
        int declaredPayloadSize = validateAndExtractSize(uploadData);

        // Step 2: Verify actual data length matches or exceeds declared size
        int actualPayloadLength = uploadData.length - HEADER_TOTAL_LENGTH;
        if (actualPayloadLength < declaredPayloadSize) {
            throw new SecurityException("Upload truncated: declared=" + declaredPayloadSize +
                    " actual=" + actualPayloadLength);
        }

        // Step 3: Compute integrity hash for audit trail
        byte[] integrityHash = computeIntegrityHash(uploadData, HEADER_TOTAL_LENGTH, declaredPayloadSize);

        // Step 4: Allocate native buffer using declared size from header
        // The native allocator adds a guard page for overflow detection
        long nativeBuffer = nativeAllocateBuffer(declaredPayloadSize);
        if (nativeBuffer == 0) {
            throw new IOException("Native buffer allocation failed");
        }

        String sessionId = UUID.randomUUID().toString();
        ProcessingSession session = new ProcessingSession(sessionId, nativeBuffer, declaredPayloadSize);
        activeSessions.put(sessionId, session);

        try {
            // Step 5: Copy payload into native buffer
            // CRITICAL: We use actualPayloadLength for the copy operation
            // to ensure all uploaded data is available to the native processor
            ByteBuffer nativeBuf = createDirectBufferFromPointer(nativeBuffer, declaredPayloadSize);
            nativeBuf.put(uploadData, HEADER_TOTAL_LENGTH, actualPayloadLength);

            // Step 6: Invoke native processing
            long outputBuffer = nativeAllocateBuffer(declaredPayloadSize * 2);
            if (outputBuffer == 0) {
                throw new IOException("Output buffer allocation failed");
            }

            try {
                int resultSize = nativeProcessImage(nativeBuffer, declaredPayloadSize,
                        outputBuffer, declaredPayloadSize * 2);

                if (resultSize < 0) {
                    throw new IOException("Native processing failed with code: " + resultSize);
                }

                // Step 7: Extract metadata
                byte[] metadata = new byte[4096];
                int metaSize = nativeExtractMetadata(nativeBuffer, declaredPayloadSize, metadata);

                return new ProcessingResult(sessionId, integrityHash,
                        Arrays.copyOf(metadata, Math.max(0, metaSize)), resultSize);
            } finally {
                nativeFreeBuffer(outputBuffer);
            }
        } finally {
            releaseSession(sessionId);
        }
    }

    /**
     * Creates a direct ByteBuffer backed by native memory at the given pointer.
     * This is a JNI helper that wraps NewDirectByteBuffer.
     */
    private static native ByteBuffer createDirectBufferFromPointer(long address, int capacity);

    /**
     * Releases native resources associated with a processing session.
     */
    public static void releaseSession(String sessionId) {
        ProcessingSession session = activeSessions.remove(sessionId);
        if (session != null && !session.released) {
            session.released = true;
            nativeFreeBuffer(session.nativeBufferPtr);
        }
    }

    /**
     * Result container for processed uploads.
     */
    public static class ProcessingResult {
        public final String sessionId;
        public final byte[] integrityHash;
        public final byte[] metadata;
        public final int outputSize;

        ProcessingResult(String sessionId, byte[] integrityHash, byte[] metadata, int outputSize) {
            this.sessionId = sessionId;
            this.integrityHash = integrityHash;
            this.metadata = metadata;
            this.outputSize = outputSize;
        }
    }
}
